{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "SRT2104, the highest-transfer analogue (0.9676), had absolute oral bioavailability of 13.8% (range 2–27%) in fasted healthy subjects using an IV 14C-microdose reference, directly placing it below the 20% threshold and supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Revefenacin, with a high transfer score of 0.9549, showed absolute oral bioavailability <3% in healthy adults, strongly supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "GHRP-6, transfer score 0.9444, had systemic oral availability of approximately 0.3% in humans, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, transfer score 0.9314, had human oral bioavailability of 0.5%, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Lopinavir, transfer score 0.9182, a peptidomimetic with a hydroxyethylene core and multiple aromatic/amide groups similar to the query, has low oral bioavailability due to first-pass metabolism and efflux.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Octreotide, transfer score 0.9077, had absolute oral bioavailability of 0.6 ± 0.4% in healthy volunteers, supporting low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence, including direct human absolute bioavailability measurements from high-transfer analogues, consistently shows oral bioavailability below 20%, with most values below 10%. The query's large, lipophilic, neutral peptidomimetic structure is consistent with these low-absorption outcomes, and the physicochemical prior also points to low F. No contradictory evidence was identified.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the exact query molecule.",
    "The exact formulation, dose, and solubility behavior of the query in the fasted state are not experimentally defined.",
    "Metabolic stability and transporter interactions of the query are inferred from analogues rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

